{
  "name": "Bambu Lab 3D打印机",
  "name_en": "Bambu Lab 3D Printer",
  "manufacturer": "Bambu Lab",
  "description": "这是一类 Bambu Lab 桌面级熔融沉积成型（FDM）3D打印机，可用于实验室中的快速原型制作、夹具治具加工、样件验证和教学演示。设备通常支持远程任务管理、打印状态监测、摄像头查看，并可结合 AMS 自动供料系统进行多材料或多色打印。",
  "description_en": "This is a family of Bambu Lab desktop fused deposition modeling (FDM) 3D printers used in laboratories for rapid prototyping, fixture and jig fabrication, sample validation, and teaching demonstrations. The printers commonly support remote job management, print-status monitoring, camera viewing, and can work with the AMS automatic material system for multi-material or multi-color printing.",
  "tag_hints": [
    "FDM 3D printing",
    "rapid prototyping",
    "AMS multi-material printing",
    "remote print monitoring",
    "printer webcam",
    "cloud print job management"
  ],
  "actions": [
    {
      "action_name": "auto-get",
      "description": "发送通用GET请求以查询打印机相关资源",
      "description_en": "send a generic GET request for printer-related resources"
    },
    {
      "action_name": "auto-post",
      "description": "发送通用POST请求以提交打印机相关资源",
      "description_en": "send a generic POST request for printer-related resources"
    },
    {
      "action_name": "auto-put",
      "description": "发送通用PUT请求以更新打印机相关资源",
      "description_en": "send a generic PUT request to update printer-related resources"
    },
    {
      "action_name": "auto-delete",
      "description": "发送通用DELETE请求以删除打印机相关资源",
      "description_en": "send a generic DELETE request to remove printer-related resources"
    },
    {
      "action_name": "auto-start_print_job",
      "description": "启动打印任务",
      "description_en": "start a print job"
    },
    {
      "action_name": "auto-start_cloud_print",
      "description": "从云端文件启动打印",
      "description_en": "start printing from a cloud-stored file"
    },
