      "description": "获取摄像头TTCode",
      "description_en": "get camera TTCode"
    },
    {
      "action_name": "auto-get_cloud_video_url",
      "description": "获取云端视频流地址",
      "description_en": "get cloud video stream URL"
    },
    {
      "action_name": "auto-get_camera_urls",
