    },
    {
      "action_name": "auto-get_slicer_resources",
      "description": "获取切片资源",
      "description_en": "get slicer resources"
    },
    {
      "action_name": "auto-get_device_info",
      "description": "获取设备详细信息",
      "description_en": "get detailed device information"
    },
    {
      "action_name": "auto-get_upload_url",
      "description": "获取文件上传地址",
      "description_en": "get file upload URL"
    }
  ]
